import{_ as t,o as a,c as s,ag as i}from"./chunks/framework.CxkNbRKf.js";const u=JSON.parse('{"title":"Data access types","description":"","frontmatter":{},"headers":[],"relativePath":"admin-guide/content/data-access-types.md","filePath":"admin-guide/content/data-access-types.md","lastUpdated":1786379412000}'),o={name:"admin-guide/content/data-access-types.md"};function n(r,e,d,l,c,p){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="data-access-types" tabindex="-1">Data access types <a class="header-anchor" href="#data-access-types" aria-label="Permalink to &quot;Data access types&quot;">​</a></h1><p>NADA allows administrators to control how users can access data on a study-by-study basis. Seven access types are available, ranging from unrestricted open access to metadata-only publication.</p><p>All access types that serve data files display terms and conditions to users before they can proceed. The terms text for each access type can be customized by administrators to reflect their organization&#39;s policies and requirements via <strong>Admin &gt; Settings &gt; Translate</strong>.</p><h2 id="quick-reference" tabindex="-1">Quick reference <a class="header-anchor" href="#quick-reference" aria-label="Permalink to &quot;Quick reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Access type</th><th>Login required</th><th>User action</th><th>Admin approval</th><th>Data served from</th></tr></thead><tbody><tr><td>Open access</td><td>No</td><td>Accept terms</td><td>No</td><td>NADA</td></tr><tr><td>Direct access</td><td>No</td><td>Accept terms</td><td>No</td><td>NADA</td></tr><tr><td>Public Use Files</td><td>Yes</td><td>Fill request form</td><td>No</td><td>NADA</td></tr><tr><td>Licensed data</td><td>Yes</td><td>Submit application</td><td><strong>Yes</strong></td><td>NADA</td></tr><tr><td>External repository</td><td>No</td><td>Click link</td><td>No</td><td>External site</td></tr><tr><td>Data enclave</td><td>No</td><td>Download PDF form</td><td>No (offline)</td><td>Secure facility</td></tr><tr><td>Data not available</td><td>—</td><td>—</td><td>—</td><td>—</td></tr></tbody></table><hr><h2 id="open-access" tabindex="-1">Open access <a class="header-anchor" href="#open-access" aria-label="Permalink to &quot;Open access&quot;">​</a></h2><p>Open access data can be downloaded and used by anyone, with virtually no restrictions. Like direct access, no login is required and users simply accept terms before downloading. The key distinction from direct access is that open access datasets should be published in <strong>open, non-proprietary file formats</strong> — such as CSV or plain text — rather than software-specific formats like SPSS (<code>.sav</code>) or Stata (<code>.dta</code>). This ensures the data is truly accessible without requiring users to have licensed software.</p><p><strong>User experience</strong></p><ol><li>User visits the dataset page — no login required.</li><li>User is shown the open data license terms and clicks to accept.</li><li>Data files are listed and can be downloaded immediately.</li></ol><p>No personal information is collected from the user.</p><p><strong>Admin workflow</strong></p><p>Set the access type to <em>Open access</em> in the dataset&#39;s Overview tab. No further configuration is needed. Ensure the data files are uploaded in open formats (CSV, etc.) and properly tagged as data files in the Resources tab — the access policy applies only to files tagged as data files.</p><p><strong>Terms &amp; conditions</strong></p><p>Yes. Terms are shown before the download list appears (language key: <code>open_data_lang</code>).</p><p><strong>When to use</strong></p><p>Use open access when the data carries no use restrictions and is published under an open license. Prepare the data files in open formats (CSV, JSON, GeoJSON, etc.) before publishing so that any user can work with the data regardless of the software they have available.</p><hr><h2 id="direct-access" tabindex="-1">Direct access <a class="header-anchor" href="#direct-access" aria-label="Permalink to &quot;Direct access&quot;">​</a></h2><p>Direct access datasets can be downloaded by anyone without registration, but the use of the data is subject to conditions (e.g., no commercial use, citation required, no re-identification of respondents).</p><p><strong>User experience</strong></p><ol><li>User visits the dataset page — no login required.</li><li>User is shown a terms and conditions page and must accept before proceeding.</li><li>Data files are listed and can be downloaded immediately.</li></ol><p>As with open access, no personal information is collected from the user.</p><p><strong>Admin workflow</strong></p><p>Set the access type to <em>Direct access</em> in the dataset&#39;s Overview tab. No approval workflow is involved. Ensure data files are correctly tagged in the Resources tab.</p><p><strong>Terms &amp; conditions</strong></p><p>Yes. Terms are shown before the download list appears, covering restrictions on redistribution, commercial use, re-identification of respondents, and citation requirements (language key: <code>direct_access_terms_lang</code>).</p><p><strong>When to use</strong></p><p>Use direct access when you want anyone to be able to download the data, but with explicit conditions of use — and when the data is distributed in software-specific formats such as SPSS or Stata. If the data is instead published in open formats with no use restrictions, use <em>Open access</em>.</p><hr><h2 id="public-use-files-puf" tabindex="-1">Public Use Files (PUF) <a class="header-anchor" href="#public-use-files-puf" aria-label="Permalink to &quot;Public Use Files (PUF)&quot;">​</a></h2><p>Public Use Files are available to any registered user who fills in a brief request form describing their intended use. No administrator approval is required — access is granted automatically once the form is submitted.</p><p><strong>User experience</strong></p><ol><li>User visits the dataset page. If not logged in, they are prompted to log in or register.</li><li>After logging in, user is shown the terms and conditions.</li><li>User fills in a request form providing their name, organization, email address, and a description of their intended use of the data.</li><li>On submission, access is granted immediately and the data files are listed for download.</li></ol><p>Once submitted, the user does not need to fill the form again for the same dataset on subsequent visits.</p><p><strong>Admin workflow</strong></p><p>Set the access type to <em>Public use files</em> in the dataset&#39;s Overview tab. No approval step is required — requests are automatically approved. Submitted requests are logged and can be reviewed in <strong>Admin &gt; Reports</strong>.</p><p>Optional: Additional custom fields can be added to the request form (e.g., research institution, project type). See <a href="/nada-documentation/installation-guide/configurations/custom-public-access-fields.html">Custom fields for public data access requests</a>.</p><p><strong>Terms &amp; conditions</strong></p><p>Yes. Terms are shown before the request form, covering redistribution, research use, re-identification, and citation requirements (language key: <code>public_access_terms_lang</code>).</p><p><strong>Collection-level access</strong></p><p>Public use access can also be granted at the collection level (bulk access), allowing users to request access to all PUF datasets within a collection in a single step. See <a href="/nada-documentation/admin-guide/web-ui/bulk-data-access.html">Bulk data access</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Use public use files when you want to track who is accessing the data and for what purpose, but do not need to review and approve each request individually.</p></div><hr><h2 id="licensed-data" tabindex="-1">Licensed data <a class="header-anchor" href="#licensed-data" aria-label="Permalink to &quot;Licensed data&quot;">​</a></h2><p>Licensed data requires users to submit a formal application that must be reviewed and approved by an administrator before any data files can be downloaded. This type is suited for sensitive or confidential datasets where access must be carefully controlled.</p><p><strong>User experience</strong></p><ol><li>User visits the dataset page. If not logged in, they are prompted to log in or register.</li><li>User fills in a detailed application form that typically includes: <ul><li>Organization and contact details</li><li>Description of the intended use of the data</li><li>Expected outputs and completion date</li><li>Research team information</li></ul></li><li>The application is submitted and the user sees a pending status.</li><li>An email notification is sent to the site administrator.</li><li>Once the administrator reviews and approves the request, the user is notified by email.</li><li>User can then return to the dataset page and download the approved files.</li></ol><p>Users can track the status of their request at any time by visiting their request page.</p><p><strong>Admin workflow</strong></p><p>Pending requests appear as alerts in the administrator dashboard and in <strong>Admin &gt; Studies &gt; Licensed requests</strong>.</p><p>For each request, the administrator can:</p><ul><li><strong>Approve</strong> — grant access to specific files, optionally setting a maximum number of downloads per file and an expiry date.</li><li><strong>Deny</strong> — reject the request with a comment sent to the applicant.</li><li><strong>Request more information</strong> — send a message to the applicant asking for clarification before deciding.</li><li><strong>Forward</strong> — forward the request to another administrator for review.</li></ul><p>Download activity for approved requests (which files were downloaded, how many times, and when) can be monitored from the licensed request detail page.</p><p>See <a href="/nada-documentation/admin-guide/web-ui/licensed-requests.html">Managing licensed data requests</a> for the full workflow.</p><p><strong>Terms &amp; conditions</strong></p><p>Yes. Terms are shown before the application form (language key: <code>licensed_access_form_lang</code>).</p><p><strong>When to use</strong></p><p>Use licensed access for datasets that are sensitive, contain potentially identifiable information, or are subject to legal or donor restrictions. This type provides the highest level of access control while still enabling online requests and approvals.</p><hr><h2 id="external-repository-remote" tabindex="-1">External repository (remote) <a class="header-anchor" href="#external-repository-remote" aria-label="Permalink to &quot;External repository (remote)&quot;">​</a></h2><p>The external repository type allows administrators to publish metadata for a dataset in NADA while directing users to another website for access to the actual data. No files are stored in or served from NADA.</p><p><strong>User experience</strong></p><ol><li>User visits the dataset page and reads the metadata.</li><li>A link to the external repository is displayed on the data access section of the page.</li><li>Clicking the link takes the user to the external site, where that site&#39;s access process applies.</li></ol><p>No login is required in NADA. No terms are shown by NADA.</p><p><strong>Admin workflow</strong></p><p>Set the access type to <em>External repository</em> and enter the URL of the external data source in the <strong>Link</strong> field in the dataset&#39;s Overview tab. The URL is stored in the <code>link_da</code> field and displayed to users on the dataset page.</p><p><strong>When to use</strong></p><p>Use this type when:</p><ul><li>The dataset originates from or is officially hosted in another repository.</li><li>You want to improve discoverability by listing the dataset in your NADA catalog, but the data owner manages access directly.</li><li>The external repository has its own access workflow (e.g., licensed access managed by another institution).</li></ul><hr><h2 id="data-enclave" tabindex="-1">Data enclave <a class="header-anchor" href="#data-enclave" aria-label="Permalink to &quot;Data enclave&quot;">​</a></h2><p>The data enclave type is used for datasets where access is restricted to a secure, supervised computing environment. Users cannot download data; instead, they must apply to visit or connect to the enclave facility.</p><p><strong>User experience</strong></p><ol><li>User visits the dataset page and reads the metadata.</li><li>The data access section displays a description of the enclave and instructions for access.</li><li>A link to a downloadable PDF application form is provided.</li><li>The user submits the completed form offline to the data archive.</li></ol><p>All subsequent steps (review, approval, scheduling, supervised data access) are managed outside of NADA.</p><p><strong>Admin workflow</strong></p><p>Set the access type to <em>Data enclave</em> in the dataset&#39;s Overview tab. There is no online workflow in NADA for managing enclave access. The PDF application form should be placed in the <code>/files/data_enclave_access.pdf</code> path on the server.</p><p>The description text shown to users (location of the enclave, access procedures, available software, etc.) can be customized via <strong>Admin &gt; Settings &gt; Translate</strong> (key: <code>data_enclave_lang</code>).</p><p><strong>When to use</strong></p><p>Use this type for highly confidential datasets where even anonymized data cannot be released outside a controlled environment. Typical use cases include census microdata with detailed geographic identifiers, administrative records linked across multiple sources, or data subject to strict legal access restrictions.</p><hr><h2 id="data-not-available" tabindex="-1">Data not available <a class="header-anchor" href="#data-not-available" aria-label="Permalink to &quot;Data not available&quot;">​</a></h2><p>This option is used when you want to publish a dataset&#39;s metadata and related materials (reports, questionnaires, technical documents) without making any data available for download or access.</p><p><strong>User experience</strong></p><p>The dataset page shows the metadata, documentation, and any external resources that have been published. There is no data access section and no download options for data files.</p><p><strong>Admin workflow</strong></p><p>Set the access type to <em>Not available</em> in the dataset&#39;s Overview tab. Published metadata and attached documents remain visible to users.</p><p><strong>When to use</strong></p><p>Use this type when:</p><ul><li>Data collection is complete but data processing or anonymization is still in progress.</li><li>The dataset exists but data sharing is not permitted.</li><li>You want to document a historical survey or study for which no data file has survived.</li><li>The study metadata contributes to discoverability or citation tracking even without data access.</li></ul><hr><h2 id="setting-the-access-type" tabindex="-1">Setting the access type <a class="header-anchor" href="#setting-the-access-type" aria-label="Permalink to &quot;Setting the access type&quot;">​</a></h2><p>The access type for a dataset is set in the <strong>Overview</strong> tab of the dataset editor in the NADA administrator interface.</p><ol><li>Go to <strong>Admin &gt; Studies &gt; Manage studies</strong>.</li><li>Click on the dataset you want to configure.</li><li>In the <strong>Data access</strong> section of the Overview tab, select the desired access type from the dropdown.</li><li>For the <em>External repository</em> type, also enter the link to the external data source.</li><li>Click <strong>Update</strong> to save.</li></ol><div class="warning custom-block"><p class="custom-block-title">Data files must be correctly tagged</p><p>The access policy applies only to files marked as data files in NADA. If a data file is uploaded as a document or other resource type, it will be publicly downloadable regardless of the access type set on the dataset. Always verify the file type in the <strong>Resources</strong> tab.</p></div><p>The access type can be changed at any time. Changing the type does not affect existing approved licensed requests.</p>',97)])])}const g=t(o,[["render",n]]);export{u as __pageData,g as default};
